type Order = { items: { name: string; qty: number; unitPrice: number }[]; taxRate: number };

export function receiptLines(order: Order): string[] {
  const lines = order.items.map((item) => `${item.qty} x ${item.name}`);
  const subtotal = order.items.reduce((sum, item) => sum + item.qty * item.unitPrice, 0);
  const tax = Math.round(subtotal * order.taxRate);
  lines.push(`Total: ${subtotal + tax}`);
  return lines;
}

files.headContent:
type Order = { items: { name: string; qty: number; unitPrice: number }[]; taxRate: number };

export function orderTotal(order: Order): number {
  const subtotal = order.items.reduce((sum, item) => sum + item.qty * item.unitPrice, 0);
  const tax = Math.round(subtotal * order.taxRate);
  return subtotal + tax;
}

export function receiptLines(order: Order): string[] {
  const lines = order.items.map((item) => `${item.qty} x ${item.name}`);
  lines.push(`Total: ${orderTotal(order)}`);
  return lines;
}
